"""Behavioral development contract for the previously exposed wraps issue."""
import asyncio
import functools
import inspect
import unittest

from boltons.funcutils import wraps, update_wrapper


class ProbeUnavailable(Exception):
    pass


class StopSignal(BaseException):
    pass


class OriginalMaintenanceContract(unittest.TestCase):
    def test_required_keyword_only_and_reverse(self):
        def source(a, b):
            return a, b

        def target(a, *, b):
            return a, b

        wrapped = wraps(source)(target)
        self.assertEqual(wrapped(3, 4), (3, 4))
        self.assertEqual(wrapped(a=3, b=4), (3, 4))
        self.assertEqual(wraps(target)(source)(3, b=4), (3, 4))
        with self.assertRaises(TypeError):
            wrapped(3)
        with self.assertRaises(TypeError):
            wrapped(3, 4, extra=5)

    def test_default_keyword_only_and_reverse(self):
        def source(a, b=10):
            return a, b

        def target(a, *, b=1):
            return a, b

        self.assertEqual(wraps(source)(target)(3), (3, 10))
        self.assertEqual(wraps(source)(target)(3, 4), (3, 4))
        self.assertEqual(wraps(target)(source)(3), (3, 1))
        self.assertEqual(wraps(target)(source)(3, b=4), (3, 4))

    def test_required_and_defaulted_parameters_with_varargs(self):
        def required(a, b, *rest, **kwargs):
            pass

        def optional(a, b=10, *rest, **kwargs):
            pass

        def target(a, *rest, b, **kwargs):
            return a, b, rest, kwargs

        for source in (required, optional):
            with self.subTest(source=source.__name__):
                wrapped = wraps(source)(target)
                self.assertEqual(wrapped(3, 4, 5, 6, flag=True), (3, 4, (5, 6), {'flag': True}))
                self.assertEqual(wrapped(3, b=4), (3, 4, (), {}))
                if source is optional:
                    self.assertEqual(wrapped(3), (3, 10, (), {}))
                else:
                    with self.assertRaises(TypeError):
                        wrapped(3)

    def test_target_wrapped_metadata_does_not_hide_real_parameters(self):
        def source(a, b, *rest):
            pass

        @functools.wraps(source)
        def target(a, *rest, b):
            return a, b, rest

        self.assertEqual(wraps(source)(target)(3, 4, 5), (3, 4, (5,)))

    def test_callable_object_and_bound_method(self):
        def source(a, b):
            pass

        class Target:
            def __call__(self, a, *, b):
                return a, b

            def method(self, a, *, b):
                return a, b

        target = Target()
        for call in (target, target.method):
            self.assertEqual(wraps(source)(call)(3, 4), (3, 4))

    def test_async_forwarding_and_business_error_identity(self):
        async def source(a, b=10, *rest):
            pass

        async def target(a, *rest, b):
            return a, b, rest

        wrapped = wraps(source)(target)
        self.assertTrue(inspect.iscoroutinefunction(wrapped))
        self.assertEqual(asyncio.run(wrapped(3)), (3, 10, ()))
        self.assertEqual(asyncio.run(wrapped(3, 4, 5)), (3, 4, (5,)))
        marker = RuntimeError('async business failure')

        async def broken(a, *rest, b):
            raise marker

        with self.assertRaises(RuntimeError) as caught:
            asyncio.run(wraps(source)(broken)(3))
        self.assertIs(caught.exception, marker)

    def test_outer_metadata_and_expected_injected_parameters(self):
        def source(a, injected, b):
            """Source documentation."""
            pass

        def target(a, *, b, extra):
            return a, b, extra

        source.tag = object()
        wrapped = update_wrapper(target, source, injected='injected', expected=[('extra', 'default')])
        self.assertEqual(wrapped(3, 4), (3, 4, 'default'))
        self.assertEqual(wrapped(3, 4, 'explicit'), (3, 4, 'explicit'))
        self.assertIs(wrapped.__wrapped__, source)
        self.assertEqual(wrapped.__name__, source.__name__)
        self.assertEqual(wrapped.__doc__, source.__doc__)
        self.assertIs(wrapped.tag, source.tag)
        self.assertEqual(list(inspect.signature(wrapped, follow_wrapped=False).parameters), ['a', 'b', 'extra'])


class ExistingBehaviorContract(unittest.TestCase):
    def test_default_keywords_remain_keywords_for_variadic_wrapper(self):
        def source(x, y, message=''):
            return x, y, message

        def target(*args, **kwargs):
            return source(*reversed(args), **kwargs)

        wrapped = wraps(source)(target)
        self.assertEqual(wrapped(3, 2, message='abc'), (2, 3, 'abc'))
        self.assertEqual(wrapped(3, 2), (2, 3, ''))

    def test_default_before_varargs_and_positional_only_forwarding(self):
        def source(x, y=1, *rest):
            return x, y, rest

        def positional(x, y=2, /, z=3):
            return x, y, z

        for original, expected in ((source, (1, 5, (7,))), (positional, (1, 5, 7))):
            def target(*args, **kwargs):
                return original(*args, **kwargs)

            wrapped = wraps(original)(target)
            self.assertEqual(wrapped(1, 5, 7), expected)
        self.assertEqual(wraps(source)(lambda *args, **kw: source(*args, **kw))(1), (1, 1, ()))

    def test_business_exception_is_not_an_optional_probe_failure(self):
        def source(a, b=10):
            pass

        for marker in (TypeError('business'), ValueError('business'), RuntimeError('business'), ProbeUnavailable('business')):
            def target(a, b=10):
                raise marker

            wrapped = wraps(source)(target)
            with self.assertRaises(type(marker)) as caught:
                wrapped(3)
            self.assertIs(caught.exception, marker)

