class FallbackCompatibilityContract(unittest.TestCase):
    def test_ordinary_exception_in_optional_metadata_preserves_forwarding(self):
        def plain(a, b=10):
            pass

        def variadic(a, b=10, *rest):
            pass

        errors = (TypeError, ValueError, RuntimeError, NotImplementedError, OSError, ProbeUnavailable)
        for error_type in errors:
            for source in (plain, variadic):
                with self.subTest(error=error_type.__name__, source=source.__name__):
                    marker = error_type('optional metadata unavailable')

                    class Target:
                        def __init__(self):
                            self.calls = []

                        @property
                        def __signature__(self):
                            raise marker

                        def __call__(self, *args, **kwargs):
                            self.calls.append((args, kwargs))
                            return args, kwargs

                    target = Target()
                    wrapped = wraps(source)(target)
                    self.assertEqual(target.calls, [])
                    if source is plain:
                        self.assertEqual(wrapped(3), ((3,), {'b': 10}))
                        self.assertEqual(wrapped(3, b=4), ((3,), {'b': 4}))
                    else:
                        self.assertEqual(wrapped(3), ((3, 10), {}))
                        self.assertEqual(wrapped(3, 4, 5), ((3, 4, 5), {}))
                    self.assertEqual(len(target.calls), 2)
                    self.assertIs(wrapped.__wrapped__, source)

    def test_fallback_then_business_exception_is_same_object(self):
        def source(a, b=10):
            pass

        for business in (TypeError('business'), ValueError('business'), RuntimeError('business'), ProbeUnavailable('business')):
            class Target:
                calls = 0

                @property
                def __signature__(self):
                    raise NotImplementedError('optional signature unavailable')

                def __call__(self, a, b=10):
                    self.calls += 1
                    raise business

            target = Target()
            wrapped = wraps(source)(target)
            self.assertEqual(target.calls, 0)
            with self.assertRaises(type(business)) as caught:
                wrapped(3)
            self.assertIs(caught.exception, business)
            self.assertEqual(target.calls, 1)


class SignalSafetyContract(unittest.TestCase):
    def test_optional_probe_must_not_swallow_baseexception(self):
        def source(a, b=10):
            pass

        for marker in (KeyboardInterrupt('probe'), SystemExit(17), asyncio.CancelledError('probe'), StopSignal('probe')):
            class Target:
                probe_reads = 0
                business_calls = 0

                @property
                def __signature__(self):
                    self.probe_reads += 1
                    raise marker

                def __call__(self, a, b=10):
                    self.business_calls += 1
                    return a, b

            target = Target()
            try:
                wrapped = wraps(source)(target)
            except BaseException as caught:
                self.assertIs(caught, marker)
                self.assertEqual(target.business_calls, 0)
            else:
                # A strategy avoiding this optional metadata is valid. If it
                # reads the property, however, the signal must propagate.
                self.assertEqual(target.probe_reads, 0)
                self.assertEqual(wrapped(3), (3, 10))

    def test_business_baseexception_and_cancellation_are_preserved(self):
        def source(a, b=10):
            pass

        for marker in (KeyboardInterrupt('business'), SystemExit(19), asyncio.CancelledError('business'), StopSignal('business')):
            def target(a, b=10):
                raise marker

            wrapped = wraps(source)(target)
            with self.assertRaises(type(marker)) as caught:
                wrapped(3)
            self.assertIs(caught.exception, marker)

    def test_async_business_cancellation_is_preserved(self):
        async def source(a, b=10):
            pass

        marker = asyncio.CancelledError('async business')

        async def target(a, b=10):
            raise marker

        with self.assertRaises(asyncio.CancelledError) as caught:
            asyncio.run(wraps(source)(target)(3))
        self.assertIs(caught.exception, marker)


